hooks.command:
cmd=$(jq -r '.tool_input.command // ""'); if echo "$cmd" | grep -qE 'gh[[:space:]]+workflow[[:space:]]+run.*release\.yml'; then tag=$(echo "$cmd" | grep -oE 'tag=v?[0-9]+\.[0-9]+\.[0-9]+' | grep -oE '[0-9]+\.[0-9]+\.[0-9]+'); if [ -z "$tag" ]; then printf '{"decision":"block","reason":"No tag=vX.Y.Z found in command. Add --field tag=vX.Y.Z"}
'; exit 0; fi; latest_raw=$(gh api repos/prasoon-pradeep/Simple-SOP/releases/latest --jq '.tag_name' 2>/dev/null); if [ -z "$latest_raw" ]; then exit 0; fi; latest=$(echo "$latest_raw" | sed 's/^v//'); higher=$(printf "%s
%s" "$tag" "$latest" | sort -V | tail -1); if [ "$higher" != "$tag" ] || [ "$tag" = "$latest" ]; then printf '{"decision":"block","reason":"Version v%s is not greater than latest release %s. Run: npm run version X.Y.Z first"}
' "$tag" "$latest_raw"; fi; fi
